/**
 * Chart.js Integration & Dynamic Mapper Script
 */

(function (global) {
    'use strict';

    const chartRegistry = new Map();

    const defaultChartOptions = {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
            legend: {
                display: true,
                position: 'top'
            },
            tooltip: {
                enabled: true
            }
        }
    };

    function normalizeDatasets(rawData, label = 'Dataset') {
        if (!rawData) return [];

        if (Array.isArray(rawData) && rawData.length > 0 && typeof rawData[0] === 'object' && rawData[0].data) {
            return rawData;
        }

        if (Array.isArray(rawData)) {
            return [{
                label: label,
                data: rawData,
                borderWidth: 2,
                tension: 0.1
            }];
        }

        return [];
    }

    function renderChartFromResponse(targetCanvas, responseData) {
        const canvas = typeof targetCanvas === 'string' 
            ? document.getElementById(targetCanvas) 
            : targetCanvas;

        if (!canvas || !(canvas instanceof HTMLCanvasElement)) {
            console.error('[ChartMapper] Invalid Canvas element target provided.');
            return null;
        }

        if (!responseData || !responseData.type) {
            console.error('[ChartMapper] Missing or invalid backend response structure.');
            return null;
        }

        const chartType = responseData.type.toLowerCase();
        const datasets = normalizeDatasets(responseData.data, responseData.title || 'Data');
        const labels = responseData.labels || [];

        if (chartRegistry.has(canvas)) {
            chartRegistry.get(canvas).destroy();
            chartRegistry.delete(canvas);
        }

        const configOptions = global.Chart.helpers.merge(
            {}, 
            [defaultChartOptions, responseData.options || {}]
        );

        const chartConfig = {
            type: chartType,
            data: {
                labels: labels,
                datasets: datasets
            },
            options: configOptions
        };

        const newChartInstance = new global.Chart(canvas.getContext('2d'), chartConfig);
        
        chartRegistry.set(canvas, newChartInstance);

        return newChartInstance;
    }

    global.ChartMapper = {
        render: renderChartFromResponse,
        getInstances: () => chartRegistry
    };

})(typeof window !== 'undefined' ? window : this);